const r = $input.all().map(i => i.json).find(c => c.chave === 'img_referencias');
let refs = []; try { refs = JSON.parse(r.valor); } catch (e) {}
return refs.map((x, i) => ({ json: { i, tam: x.length, data: x } }));

const H = { 'x-magnific-api-key': 'MSa5f0036a21e0445589b0d96fdb4079ba', 'Content-Type': 'application/json' };
const t0 = Date.now();
const pedir = async (i) => {
  const s = Date.now();
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.magnific.com/v1/ai/text-to-image/flux-pro-v1-1', headers: H, json: true, timeout: 30000, body: { prompt: 'minimal dark grey studio backdrop, wine red light ' + i, aspect_ratio: 'social_story_9_16', output_format: 'jpeg' } });
    return { json: { i, ok: true, task: r.data.task_id, ms: Date.now() - s } };
  } catch (e) { return { json: { i, ok: false, erro: String(e.message).slice(0, 200), ms: Date.now() - s } }; }
};
const out = await Promise.all([1, 2, 3].map(pedir));
out.push({ json: { total_ms: Date.now() - t0 } });
return out;

const ctxHz = $('Montar contexto').first().json;
const hz = ctxHz.formato === 'Vídeo' && /youtube/i.test(ctxHz.canal || '');
const H = { 'x-magnific-api-key': 'MSa5f0036a21e0445589b0d96fdb4079ba', 'Content-Type': 'application/json' };
const cfg = Object.fromEntries($('Buscar configuração').all().map(i => [i.json.chave, i.json.valor]));
let refs = [];
try { refs = JSON.parse(cfg.img_referencias || '[]'); } catch (e) {}
refs = refs.slice(0, 4).map(x => String(x).replace(/^data:[^,]+,/, ''));
const modelo = refs.length ? 'flux-2-pro' : 'flux-pro-v1-1';
const cenas = $input.first().json.output?.cenas || [];
if (!cenas.length) throw new Error('A Clara não conseguiu preparar as cenas do roteiro (o modelo não devolveu o formato esperado)');
const tentar = async (req, vezes = 2) => { for (let t = 1; ; t++) { try { return await this.helpers.httpRequest({ ...req, timeout: 30000 }); } catch (e) { if (t >= vezes) throw e; await new Promise(r => setTimeout(r, 3000)); } } };
const simples = (c) => ({ prompt: c.prompt_imagem, aspect_ratio: hz ? 'widescreen_16_9' : 'social_story_9_16', output_format: 'jpeg' });
const pedir = async (c, i) => {
  const body = refs.length
    ? Object.assign({ prompt: c.prompt_imagem, width: hz ? 1440 : 810, height: hz ? 810 : 1440 }, ...refs.map((x, j) => ({ [j ? 'input_image_' + (j + 1) : 'input_image']: x })))
    : simples(c);
  let r = null, usado = modelo;
  try { r = await tentar({ method: 'POST', url: 'https://api.magnific.com/v1/ai/text-to-image/' + modelo, headers: H, body, json: true }); }
  catch (e) {
    usado = 'flux-pro-v1-1';
    try { r = await tentar({ method: 'POST', url: 'https://api.magnific.com/v1/ai/text-to-image/flux-pro-v1-1', headers: H, json: true, body: simples(c) }); } catch (e2) { r = null; }
  }
  const palavras = String(c.locucao || '').split(/\s+/).filter(Boolean).length;
  return { json: { numero: Number(c.numero) || i + 1, rodada: $runIndex, prompt_imagem: c.prompt_imagem, prompt_movimento: c.prompt_movimento || '', locucao: c.locucao || '', duracao: palavras > 11 ? '10' : '5', modelo_img: usado, img_task: r?.data?.task_id || '', imagem_falhou: !r, tent: 0, hz } };
};
return await Promise.all(cenas.map(pedir));

const H = { 'x-magnific-api-key': 'MSa5f0036a21e0445589b0d96fdb4079ba' };
const itens = $input.all().map(i => ({ ...i.json }));
for (const j of itens) {
  j.tent = (j.tent || 0) + 1;
  if (j.imagem_url || j.imagem_falhou || !j.img_task) continue;
  let r = null;
  try { r = await this.helpers.httpRequest({ url: 'https://api.magnific.com/v1/ai/text-to-image/' + j.modelo_img + '/' + j.img_task, headers: H, json: true, timeout: 15000 }); } catch (e) { continue; }
  if (r.data.status === 'COMPLETED') j.imagem_url = r.data.generated[0];
  if (r.data.status === 'FAILED') j.imagem_falhou = true;
}
const prontas = itens.every(j => j.imagem_url || j.imagem_falhou) || (itens[0]?.tent || 0) >= 10;
return itens.map(j => ({ json: { ...j, todas_prontas: prontas } }));

const H = { 'x-magnific-api-key': 'MSa5f0036a21e0445589b0d96fdb4079ba', 'Content-Type': 'application/json' };
const cfg = Object.fromEntries($('Buscar configuração').all().map(i => [i.json.chave, i.json.valor]));
const voz = cfg.video_voz || '21m00Tcm4TlvDq8ikWAM';
const tentar = async (req, vezes = 2) => { for (let t = 1; ; t++) { try { return await this.helpers.httpRequest({ ...req, timeout: 30000 }); } catch (e) { if (t >= vezes) throw e; await new Promise(r => setTimeout(r, 3000)); } } };
const animar = async (it) => {
  const j = { ...it.json, tent: 0 };
  if (!j.imagem_url) return null;
  const [v, a] = await Promise.all([
    tentar({ method: 'POST', url: 'https://api.magnific.com/v1/ai/image-to-video/kling-v2-6-pro', headers: H, json: true,
      body: { image: j.imagem_url, prompt: j.prompt_movimento || 'subtle cinematic motion', duration: j.duracao, aspect_ratio: j.hz ? 'widescreen_16_9' : 'social_story_9_16', cfg_scale: 0.5, generate_audio: false } }).catch(() => null),
    j.locucao ? tentar({ method: 'POST', url: 'https://api.magnific.com/v1/ai/voiceover/elevenlabs-turbo-v2-5', headers: H, json: true,
      body: { text: j.locucao, voice_id: voz, speed: 1.0, stability: 0.5, similarity_boost: 0.5, use_speaker_boost: true } }).catch(() => null) : Promise.resolve(null),
  ]);
  j.video_task = v?.data?.task_id || '';
  if (!v) j.video_falhou = true;
  j.audio_task = a?.data?.task_id || '';
  return { json: j };
};
const out = (await Promise.all($input.all().map(animar))).filter(Boolean);
return out.length ? out : [{ json: { sem_cenas: true } }];

const H = { 'x-magnific-api-key': 'MSa5f0036a21e0445589b0d96fdb4079ba' };
const itens = $input.all().map(i => ({ ...i.json })).filter(j => !j.sem_cenas);
const pegar = async (url) => { try { return await this.helpers.httpRequest({ url, headers: H, json: true, timeout: 15000 }); } catch (e) { return null; } };
for (const j of itens) {
  j.tent = (j.tent || 0) + 1;
  if (!j.video_url && !j.video_falhou && j.video_task) {
    const r = await pegar('https://api.magnific.com/v1/ai/image-to-video/kling-v2-6/' + j.video_task);
    if (r?.data?.status === 'COMPLETED') j.video_url = r.data.generated[0];
    if (r?.data?.status === 'FAILED') j.video_falhou = true;
  }
  if (j.audio_task && !j.audio_url && !j.audio_falhou) {
    const r = await pegar('https://api.magnific.com/v1/ai/voiceover/elevenlabs-turbo-v2-5/' + j.audio_task);
    if (r?.data?.status === 'COMPLETED') j.audio_url = r.data.generated[0];
    if (r?.data?.status === 'FAILED') j.audio_falhou = true;
  }
}
const pronto = (j) => (j.video_url || j.video_falhou) && (!j.audio_task || j.audio_url || j.audio_falhou);
const todos = !itens.length || itens.every(pronto) || (itens[0]?.tent || 0) >= 20;
return (itens.length ? itens : [{ sem_cenas: true }]).map(j => ({ json: { ...j, todos_prontos: todos } }));

const itens = $input.all().map(i => i.json).filter(j => j.video_url).sort((a, b) => a.numero - b.numero);
if (!itens.length) throw new Error('Nenhuma cena de vídeo ficou pronta no Magnific');
const peca = $('Montar contexto').first().json.peca_id;
const rodada = itens[0]?.rodada ?? 0;
const prefixo = peca + '/r' + rodada + '-' + Date.now();
const dir = '/home/node/.n8n-files/galera/' + prefixo.replace(/\//g, '_');
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const linhas = [
  'set -e',
  'F=/tmp/ffmpeg; [ -x $F ] || (wget -q -O /tmp/ffmpeg.gz https://github.com/eugeneware/ffmpeg-static/releases/download/b6.0/ffmpeg-linux-x64.gz && gunzip -f /tmp/ffmpeg.gz && chmod +x $F)',
  'rm -rf ' + q(dir) + ' && mkdir -p ' + q(dir) + ' && cd ' + q(dir),
];
const lista = [];
const T = itens[0]?.hz ? '1280:720' : '720:1280';
const vf = '[0:v]scale=' + T + ':force_original_aspect_ratio=increase,crop=' + T + ',setsar=1,fps=30[v]';
for (const j of itens) {
  const n = String(j.numero).padStart(2, '0');
  linhas.push('wget -q -O v' + n + '.mp4 ' + q(j.video_url));
  if (j.audio_url) {
    linhas.push('wget -q -O a' + n + '.mp3 ' + q(j.audio_url));
    linhas.push('$F -y -loglevel error -i v' + n + '.mp4 -i a' + n + '.mp3 -filter_complex "' + vf + ';[1:a]apad[a]" -map "[v]" -map "[a]" -shortest -c:v libx264 -preset veryfast -pix_fmt yuv420p -c:a aac -ar 44100 -ac 2 cena-' + n + '.mp4');
  } else {
    linhas.push('$F -y -loglevel error -i v' + n + '.mp4 -f lavfi -i anullsrc=r=44100:cl=stereo -filter_complex "' + vf + '" -map "[v]" -map 1:a -shortest -c:v libx264 -preset veryfast -pix_fmt yuv420p -c:a aac -ar 44100 -ac 2 cena-' + n + '.mp4');
  }
  lista.push("file 'cena-" + n + ".mp4'");
}
linhas.push("printf '%s\\n' " + lista.map(l => q(l)).join(' ') + ' > lista.txt');
linhas.push('$F -y -loglevel error -f concat -safe 0 -i lista.txt -c copy video-final.mp4');
linhas.push('rm -f v*.mp4 a*.mp3 lista.txt && ls -la');
return [{ json: { cmd: linhas.join('\n'), dir, prefixo, rodada, cenas: itens.map(j => ({ numero: j.numero, locucao: j.locucao, prompt: j.prompt_imagem, duracao: Number(j.duracao) })) } }];

const m = $('Comando de montagem').first().json;
const base = 'https://alrnajijumqvxzmogwpy.supabase.co/storage/v1/object/public/galera/' + m.prefixo + '/';
const nomes = $('Ler arquivos do vídeo').all().map(i => i.binary?.data?.fileName).filter(Boolean);
return [{ json: { nomes, base, ffmpeg: $('Montar vídeo (ffmpeg)').first().json } }];
